add_filter( 'woocommerce_coupon_is_valid_for_product', 'perfectpixel_exclude_products_from_coupons', 9999, 2 );

function perfectpixel_exclude_products_from_coupons( $valid, $product ) {
	$excluded = wp_parse_id_list( '{{no_coupon_product_ids}}' );
	if ( ! $excluded || ! $product ) {
		return $valid;
	}
	$id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	return in_array( $id, $excluded, true ) ? false : $valid;
}
